		void RunFunctionAndAssertRetainedEarnings(string branchFilter, object retainedEarningsThisPeriod, object retainedEarningsYearToDate)
		{
			DataTable result = DataUtils.GetDataTableFromQuery(TestConnection, "SELECT * FROM dbo.ProfitAndLossRetainedEarnings (201009, '878D7ACA-FFC3-49FC-9710-969CA0C0F2AC', '" + branchFilter + "', '')");
			AssertEquals("Row count == 1", 1, result.Rows.Count);
			AssertEquals("Retained Earnings This Period", retainedEarningsThisPeriod, result.Rows[0]["CurrentPeriod"]);
			AssertEquals("Retained Earnings Year To Date", retainedEarningsYearToDate, result.Rows[0]["YearToPeriod"]);
		}

		public void TestTransactionCategoryGroup()
		{
			var helper = new TestDbHelper(TestConnection);
			var branchCode = "CBH";
			var currentBranch = helper.InsertBranch(branchCode, TestDbHelper.DefaultCompanyPK);

			helper.SetRegistryPLAppropriationAccount(helper.GLAccountPK1);

			var categotyGroups = TestHelper.CreateGLAggregate(helper, "A", 26, 100, 202001, helper.GLAccountPK1, helper.DefaultDepartmentPK, currentBranch, TestDbHelper.DefaultCompanyPK);

			var sqlText = $"SELECT * FROM RawPLBSHALTAccDepRetainedEarnings(202001,202001,202001,'{TestDbHelper.DefaultCompanyPK}','{branchCode}','{"{0}"}')";

			var result = DataUtils.GetDataTableFromQuery(TestConnection, string.Format(sqlText, "A00"));
			AssertEquals("Result should have one row", 1, result.Rows.Count);
			AssertEquals("singe category", 100m, result.Rows[0]["Amount"]);

			result = DataUtils.GetDataTableFromQuery(TestConnection, string.Format(sqlText, categotyGroups));
			AssertEquals("Result should have one row", 1, result.Rows.Count);
			AssertEquals("maximum group is 25", 2500m, result.Rows[0]["Amount"]);
		}
	}
